{"file_path": "/Users/jie/Documents/workspace/lcmhalgen/posixGen_Demos/UART_Hyperterminal_IT/Drivers/STM32F4xx_HAL_Driver/Src/stm32f4xx_hal_uart.c", "replaced_function_infos": [{"function_name": "UART_Start_Receive_DMA", "function_type": "RECV", "functionality": "Starts DMA-based UART receive operation by configuring DMA to transfer data from UART receive register to user buffer, setting up DMA callbacks, and enabling UART interrupts for error handling during reception", "classification_reason": "This function performs critical data reception operations via DMA from UART peripheral to user buffer. It sets up DMA transfer from UART RDR register to user buffer, configures DMA callbacks for receive completion, and enables UART interrupts specifically for data reception error handling. The primary purpose is data reception, making it a RECV function.", "has_replacement": true, "function_replacement": "HAL_StatusTypeDef UART_Start_Receive_DMA(UART_HandleTypeDef *huart, uint8_t *pData, uint16_t Size)
{
  huart->pRxBuffPtr = pData;
  huart->RxXferSize = Size;

  huart->ErrorCode = HAL_UART_ERROR_NONE;
  huart->RxState = HAL_UART_STATE_BUSY_RX;

  if (huart->hdmarx != NULL)
  {
    /* Set the UART DMA transfer complete callback */
    huart->hdmarx->XferCpltCallback = UART_DMAReceiveCplt;

    /* Set the UART DMA Half transfer complete callback */
    huart->hdmarx->XferHalfCpltCallback = UART_DMARxHalfCplt;

    /* Set the DMA error callback */
    huart->hdmarx->XferErrorCallback = UART_DMAError;

    /* Set the DMA abort callback */
    huart->hdmarx->XferAbortCallback = NULL;

    /* Replace DMA receive with POSIX equivalent */
    int received = HAL_BE_In(pData, Size);
    if (received < 0)
    {
      /* Set error code to DMA */
      huart->ErrorCode = HAL_UART_ERROR_DMA;

      /* Restore huart->RxState to ready */
      huart->RxState = HAL_UART_STATE_READY;

      return HAL_ERROR;
    }
    else if (received == Size)
    {
      /* If all data received, call completion callback */
      if (huart->hdmarx->XferCpltCallback != NULL)
      {
        huart->hdmarx->XferCpltCallback(huart->hdmarx);
      }
    }
  }

  /* Skip UART interrupt enable operations as they are peripheral-specific */

  return HAL_OK;
}"}, {"function_name": "HAL_UART_Transmit_DMA", "function_type": "RECV", "functionality": "Sends data through UART using DMA (Direct Memory Access) for transmission. Configures DMA transfer, sets up callbacks, manages UART state machine, and enables DMA transfer via peripheral register access.", "classification_reason": "This function performs critical data I/O operations (UART transmission) using DMA. It involves peripheral register access (TDR, CR3), manages data transmission flow, and handles DMA-based data transfer which is a key peripheral operation. Although it contains interrupt-related operations through DMA callbacks, the primary functionality is data transmission, making it suitable for the RECV category.", "has_replacement": true, "function_replacement": "HAL_StatusTypeDef HAL_UART_Transmit_DMA(UART_HandleTypeDef *huart, const uint8_t *pData, uint16_t Size)
{
  /* Check that a Tx process is not already ongoing */
  if (huart->gState == HAL_UART_STATE_READY)
  {
    if ((pData == NULL) || (Size == 0U))
    {
      return HAL_ERROR;
    }

    huart->pTxBuffPtr  = pData;
    huart->TxXferSize  = Size;
    huart->TxXferCount = Size;

    huart->ErrorCode = HAL_UART_ERROR_NONE;
    huart->gState = HAL_UART_STATE_BUSY_TX;

    if (huart->hdmatx != NULL)
    {
      /* Set the UART DMA transfer complete callback */
      huart->hdmatx->XferCpltCallback = UART_DMATransmitCplt;

      /* Set the UART DMA Half transfer complete callback */
      huart->hdmatx->XferHalfCpltCallback = UART_DMATxHalfCplt;

      /* Set the DMA error callback */
      huart->hdmatx->XferErrorCallback = UART_DMAError;

      /* Set the DMA abort callback */
      huart->hdmatx->XferAbortCallback = NULL;

      /* Replace DMA transfer with POSIX output */
      HAL_BE_Out(Size);
    }

    return HAL_OK;
  }
  else
  {
    return HAL_BUSY;
  }
}"}, {"function_name": "UART_Receive_IT", "function_type": "RECV", "functionality": "UART data reception in interrupt mode - handles receiving data from UART peripheral using interrupt-driven approach", "classification_reason": "Function name indicates UART data reception with interrupt mode ('_IT' suffix), which performs critical data I/O operations from peripheral hardware. This is a typical RECV category function that handles data transfer from UART peripheral and would need redirection to POSIX-equivalent interfaces.", "has_replacement": true, "function_replacement": "// UART_Receive_IT replacement - redirect UART data reception to POSIX interface
